# SCD Type 2 拉链表实现：维度变更流 -> start_date / end_date / is_current
import datetime

END_OF_TIME = "9999-12-31"


def minus_one_day(s):
    d = datetime.date.fromisoformat(s)
    return (d - datetime.timedelta(days=1)).isoformat()


# (生效日期, 用户主键, (城市, 会员等级))
CHANGE_LOG = [
    ("2026-01-01", "U001", ("北京", "V1")),
    ("2026-02-01", "U001", ("北京", "V2")),
    ("2026-02-15", "U001", ("上海", "V2")),
    ("2026-03-01", "U001", ("上海", "V2")),   # 与上一版本属性完全相同 -> 合并
    ("2026-01-01", "U002", ("广州", "V1")),
    ("2026-03-01", "U002", ("深圳", "V1")),
]


def build_zipper(change_log):
    by_key = {}
    for eff, key, attrs in change_log:
        by_key.setdefault(key, []).append((eff, attrs))
    rows = []
    for key in sorted(by_key):
        events = sorted(by_key[key], key=lambda x: x[0])
        versions = []
        for eff, attrs in events:
            if versions and versions[-1][1] == attrs:
                continue           # 属性无实质变化，不产生新版本
            versions.append((eff, attrs))
        for i, (eff, attrs) in enumerate(versions):
            if i + 1 < len(versions):
                end = minus_one_day(versions[i + 1][0])
                is_current = 0
            else:
                end = END_OF_TIME
                is_current = 1
            rows.append((key, attrs[0], attrs[1], eff, end, is_current))
    return rows


def lookup(rows, key, biz_date):
    """按业务日期取该时刻有效的维度版本。"""
    for r in rows:
        if r[0] == key and r[3] <= biz_date <= r[4]:
            return (r[1], r[2])
    return None


rows = build_zipper(CHANGE_LOG)

print("== SCD Type 2 拉链记录（按主键, start_date 排序） ==")
print("user_sk | city | level | start_date  | end_date    | is_current")
for key, city, level, start, end, cur in rows:
    print(key + "    | " + city + "   | " + level + "     | " + start +
          " | " + end + " | " + str(cur))

raw_events = len(CHANGE_LOG)
versions = len(rows)
print("")
print("原始变更事件数 = " + str(raw_events))
print("合并『属性无变化』后的有效版本数 = " + str(versions))
print("被合并掉（未产生新版本）的事件数 = " + str(raw_events - versions))
current_cnt = sum(1 for r in rows if r[5] == 1)
print("is_current=1 的记录数（应等于主键数 2） = " + str(current_cnt))

# 每个主键的拉链必须连续且无缝：前一段 end + 1 天 == 后一段 start
seamless = True
for key in sorted(set(r[0] for r in rows)):
    seg = [r for r in rows if r[0] == key]
    for i in range(len(seg) - 1):
        if minus_one_day(seg[i + 1][3]) != seg[i][4]:
            seamless = False
print("拉链无缝相邻（前一段 end + 1 天 == 后一段 start）: " + str(seamless))

for d in ["2026-01-10", "2026-02-20", "2026-04-01"]:
    got = []
    for key in sorted(set(r[0] for r in rows)):
        v = lookup(rows, key, d)
        got.append(key + "=" + v[0] + "/" + v[1])
    print("时点快照 " + d + ": " + ", ".join(got))

print("")
print("判据 1（重复事件被合并，6 条变更 -> 5 个版本）: " + str(raw_events == 6 and versions == 5))
print("判据 2（每条主键恰好一条 is_current=1）: " + str(current_cnt == 2))
print("判据 3（拉链时间轴连续无缝）: " + str(seamless))
